import{b as t,O as i,g as a,j as e}from"./chunks/framework.DcaUmd3X.js";const k=JSON.parse('{"title":"版本回退","description":"","frontmatter":{},"headers":[],"relativePath":"git/basics/reset/index.md","filePath":"Git操作手册/2.基础操作/04.版本回退.md","lastUpdated":1782199931000}'),d={name:"git/basics/reset/index.md"};function h(n,s,l,p,o,r){return i(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="版本回退" tabindex="-1">版本回退 <a class="header-anchor" href="#版本回退" aria-label="Permalink to &quot;版本回退&quot;">​</a></h1><blockquote><p>git reset / git revert / git reflog，改错了？退回去。</p></blockquote><h2 id="什么时候需要回退" tabindex="-1">什么时候需要回退 <a class="header-anchor" href="#什么时候需要回退" aria-label="Permalink to &quot;什么时候需要回退&quot;">​</a></h2><p>日常翻车场景：</p><ul><li>&quot;刚才的提交把东西改坏了，想倒回去&quot;</li><li>&quot;commit 信息写错了，想改一下&quot;</li><li>&quot;push 完了才发现不该提交这个文件&quot;</li></ul><p>Git 提供了多种回退方式，区别在于<strong>回退多远、会不会丢东西</strong>。</p><h2 id="先学会看-后悔药-的编号" tabindex="-1">先学会看&quot;后悔药&quot;的编号 <a class="header-anchor" href="#先学会看-后悔药-的编号" aria-label="Permalink to &quot;先学会看&quot;后悔药&quot;的编号&quot;">​</a></h2><p>每次提交都有一个唯一的 commit id，是一串 40 位的哈希值。回退时需要指定&quot;回退到哪个提交&quot;：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oneline</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># a1b2c3d 第三次提交</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># e4f5a6b 第二次提交</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># c7d8e9f 第一次提交</span></span></code></pre></div><p>记下你要回到的那个 commit id（前几位就够了）。</p><h2 id="撤销工作区的修改" tabindex="-1">撤销工作区的修改 <a class="header-anchor" href="#撤销工作区的修改" aria-label="Permalink to &quot;撤销工作区的修改&quot;">​</a></h2><p>还没 <code>git add</code>，只是改了文件。改乱了想还原——丢掉所有改动，回到最近一次 commit 的状态：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restore</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 文件名</span></span></code></pre></div><p>这个操作不可逆——改动直接被丢弃，无法恢复。用之前确认你真的不想要这些修改了。</p><h2 id="撤销暂存区的修改" tabindex="-1">撤销暂存区的修改 <a class="header-anchor" href="#撤销暂存区的修改" aria-label="Permalink to &quot;撤销暂存区的修改&quot;">​</a></h2><p>已经 <code>git add</code> 了，但还没 <code>commit</code>。想把文件从暂存区拉回工作区：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restore</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --staged</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 文件名</span></span></code></pre></div><p>文件回到&quot;已修改但未暂存&quot;的状态，改动还在，只是不再参与下一次提交。</p><h2 id="新旧命令对照" tabindex="-1">新旧命令对照 <a class="header-anchor" href="#新旧命令对照" aria-label="Permalink to &quot;新旧命令对照&quot;">​</a></h2><p>你在网上搜到的教程可能用的是旧版写法，其实做的事情完全一样：</p><table tabindex="0"><thead><tr><th>新版命令</th><th>旧版命令</th><th>作用</th></tr></thead><tbody><tr><td><code>git restore 文件名</code></td><td><code>git checkout -- 文件名</code></td><td>撤销工作区修改</td></tr><tr><td><code>git restore --staged 文件名</code></td><td><code>git reset HEAD 文件名</code></td><td>撤销暂存区</td></tr></tbody></table><p>新版（Git 2.23+）把 <code>checkout</code> 和 <code>reset</code> 的&quot;撤销&quot;功能独立拆到了 <code>restore</code>，命令名和用途更匹配——<code>restore</code> 就是&quot;还原&quot;。如果你用的 Git 版本 &gt;= 2.23（大概率是），优先用新版。</p><h2 id="修改最后一次提交" tabindex="-1">修改最后一次提交 <a class="header-anchor" href="#修改最后一次提交" aria-label="Permalink to &quot;修改最后一次提交&quot;">​</a></h2><p>提交完了发现漏了文件、或者提交信息写错了，用 amend 修补：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 漏了文件？补上</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 漏掉的文件</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --amend</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 仅仅是提交信息写错了？</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --amend</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;正确的提交信息&quot;</span></span></code></pre></div><p><code>--amend</code> 不会增加新提交，而是<strong>替换</strong>最后一次提交。注意：如果已经 push 了，amend 后需要 <code>git push --force</code>。没有 push 的话随便改。</p><h2 id="回到上一个版本-head-和-head-n" tabindex="-1">回到上一个版本：HEAD^ 和 HEAD~N <a class="header-anchor" href="#回到上一个版本-head-和-head-n" aria-label="Permalink to &quot;回到上一个版本：HEAD^ 和 HEAD~N&quot;">​</a></h2><p>每次回退都要先 <code>git log</code> 查 commit id，很烦。Git 提供了快捷方式：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HEAD^</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 上一个版本（等同于 HEAD~1）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HEAD^^</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 上上个版本</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HEAD~1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 上一个版本</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HEAD~3</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 往前数 3 个版本</span></span></code></pre></div><p>大多数时候你只需要&quot;回到上一个&quot;——直接用 <code>HEAD^</code>，不用查 commit id。</p><h2 id="回退到历史版本-git-reset" tabindex="-1">回退到历史版本：git reset <a class="header-anchor" href="#回退到历史版本-git-reset" aria-label="Permalink to &quot;回退到历史版本：git reset&quot;">​</a></h2><p>提交了好几个版本，想回到之前的某个版本：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --soft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  commit_id</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 退回提交，改动保留在暂存区</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mixed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit_id</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 退回提交，改动保留在工作区（默认）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --hard</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  commit_id</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 退回提交，改动全部丢弃</span></span></code></pre></div><p>把 <code>commit_id</code> 换成 <code>HEAD^</code> 就能回到上一个版本。</p><p>用一张表说清楚区别：</p><table tabindex="0"><thead><tr><th>模式</th><th>commit 回退</th><th>暂存区</th><th>工作区</th><th>什么时候用</th></tr></thead><tbody><tr><td><code>--soft</code></td><td>✅ 回退</td><td>保留</td><td>保留</td><td>合并多个 commit，重新提交</td></tr><tr><td><code>--mixed</code></td><td>✅ 回退</td><td>清空</td><td>保留</td><td>撤回 commit 和 add，重新挑选</td></tr><tr><td><code>--hard</code></td><td>✅ 回退</td><td>清空</td><td>清空</td><td>彻底不要了，回到干净状态</td></tr></tbody></table><p>大多数时候用 <code>--soft</code> 就够了——退回提交但改动还在，重新 <code>commit</code> 一次。</p><h2 id="已-push-的提交怎么撤销-git-revert" tabindex="-1">已 push 的提交怎么撤销：git revert <a class="header-anchor" href="#已-push-的提交怎么撤销-git-revert" aria-label="Permalink to &quot;已 push 的提交怎么撤销：git revert&quot;">​</a></h2><p><code>git reset</code> 改的是本地历史。如果那个提交已经推送到 GitHub 了，同事可能已经拉取了——这时候用 reset 会炸，因为你的历史和远程不一致了。</p><p>安全的做法是用 <code>git revert</code>——<strong>新建一个&quot;反向提交&quot;，把指定提交的改动抵消掉</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revert</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit_id</span></span></code></pre></div><p>它不会删除历史，而是生成一条新提交：&quot;撤销了之前的某某改动&quot;。历史是完整的，推送也不需要 <code>--force</code>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>原来：  A → B → C（C 是 bug 提交，已经 push）</span></span>
<span class="line"><span>revert：A → B → C → D（D 是 C 的反操作，撤销了 C 的改动）</span></span></code></pre></div><h2 id="踩了-hard-reset-后悔怎么办-git-reflog" tabindex="-1">踩了 hard reset 后悔怎么办：git reflog <a class="header-anchor" href="#踩了-hard-reset-后悔怎么办-git-reflog" aria-label="Permalink to &quot;踩了 hard reset 后悔怎么办：git reflog&quot;">​</a></h2><p><code>--hard</code> 清掉了改动，过了一会又想要回来——还有救吗？有。Git 悄悄记录了 HEAD 的所有移动：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reflog</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># a1b2c3d HEAD@{0}: commit: 第三次提交</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># e4f5a6b HEAD@{1}: commit: 第二次提交</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># e4f5a6b HEAD@{2}: reset: moving to e4f5a6b   ← 这次 reset 也在记录里</span></span></code></pre></div><p>找到你 reset 之前的那个 commit id，再 reset 回去：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --hard</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> a1b2c3d</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 又回到第三次提交了</span></span></code></pre></div><blockquote><p>💡 <code>reflog</code> 是 Git 的&quot;后悔药之后悔药&quot;——只要 commit 过，哪怕 hard reset 了也找得回来。但前提是 commit 过。没 commit 的改动 reset 了是真的没了。</p></blockquote><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>回退的路线图，按&quot;改到哪一步了&quot;来选：</p><table tabindex="0"><thead><tr><th>场景</th><th>命令</th></tr></thead><tbody><tr><td>改了文件还没 add</td><td><code>git restore 文件名</code></td></tr><tr><td>add 了还没 commit</td><td><code>git restore --staged 文件名</code></td></tr><tr><td>commit 了还没 push</td><td><code>git reset --soft commit_id</code> 或 <code>--amend</code></td></tr><tr><td>已经 push 了</td><td><code>git revert commit_id</code></td></tr><tr><td>各种 reset 后后悔</td><td><code>git reflog</code> 找回</td></tr></tbody></table><h2 id="自主练习" tabindex="-1">自主练习 <a class="header-anchor" href="#自主练习" aria-label="Permalink to &quot;自主练习&quot;">​</a></h2><ol><li>做三次提交，用 <code>git reset --soft</code> 退回到第一次，观察暂存区和工作区的变化</li><li>分别尝试 <code>--soft</code>、<code>--mixed</code>、<code>--hard</code> 三种 reset，对比差异</li><li>提交一个&quot;错误&quot;的改动，用 <code>git revert</code> 撤销它，观察 git log 的变化</li><li>执行一次 <code>--hard</code> 回退后，用 <code>git reflog</code> 找回&quot;丢失&quot;的提交</li></ol>`,54)])])}const g=t(d,[["render",h]]);export{k as __pageData,g as default};
